package com.maxhitcalculator;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("maxhitcalculator")
public interface MaxHitConfig extends Config
{
	@ConfigItem(
			keyName = "magicBaseHit",
			name = "Fallback Magic Base Hit",
			description = "Used when the plugin cannot automatically identify the spell or powered staff.",
			position = 0
	)
	@Range(
			min = 0,
			max = 1000
	)
	default int magicBaseHit()
	{
		return 0;
	}
}

package com.maxhitcalculator;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Locale;

import javax.inject.Inject;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class MaxHitOverlay
        extends OverlayPanel
{
    private final MaxHitPlugin plugin;

    @Inject
    public MaxHitOverlay(
            MaxHitPlugin plugin)
    {
        this.plugin = plugin;

        setPosition(
                OverlayPosition.TOP_LEFT
        );

        panelComponent.setPreferredSize(
                new Dimension(225, 0)
        );
    }

    @Override
    public Dimension render(
            Graphics2D graphics)
    {
        panelComponent
                .getChildren()
                .add(
                        TitleComponent.builder()
                                .text("MAX HIT CALCULATOR")
                                .color(Color.ORANGE)
                                .build()
                );

        switch (plugin.getCombatType())
        {
            case RANGED:
                renderRanged();
                break;

            case MAGIC:
                renderMagic();
                break;

            case MELEE:
            default:
                renderMelee();
                break;
        }

        return super.render(graphics);
    }

    private void renderMelee()
    {
        addTitle(
                "MELEE",
                Color.RED
        );

        addLine(
                "Weapon",
                plugin.getWeaponName(),
                Color.WHITE
        );

        addLine(
                "MAX HIT",
                String.valueOf(
                        plugin.getMeleeMaxHit()
                ),
                Color.GREEN
        );

        addLine(
                "Strength",
                String.valueOf(
                        plugin.getStrengthLevel()
                ),
                Color.WHITE
        );

        addLine(
                "Gear STR",
                formatBonus(
                        plugin
                                .getMeleeStrengthBonus()
                ),
                Color.WHITE
        );

        addLine(
                "Style",
                plugin.getAttackStyle(),
                Color.WHITE
        );

        addLine(
                "Style STR",
                formatBonus(
                        plugin.getMeleeStyleBonus()
                ),
                Color.WHITE
        );

        addLine(
                "Prayer",
                plugin.getMeleePrayer(),
                prayerColor(
                        plugin.getMeleePrayer()
                )
        );
    }

    private void renderRanged()
    {
        addTitle(
                "RANGED",
                Color.GREEN
        );

        addLine(
                "Weapon",
                plugin.getWeaponName(),
                Color.WHITE
        );

        addLine(
                "MAX HIT",
                String.valueOf(
                        plugin.getRangedMaxHit()
                ),
                Color.GREEN
        );

        addLine(
                "Ranged",
                String.valueOf(
                        plugin.getRangedLevel()
                ),
                Color.WHITE
        );

        addLine(
                "Ranged STR",
                formatBonus(
                        plugin
                                .getRangedStrengthBonus()
                ),
                Color.WHITE
        );

        addLine(
                "Style",
                plugin.getAttackStyle(),
                Color.WHITE
        );

        addLine(
                "Prayer",
                plugin.getRangedPrayer(),
                prayerColor(
                        plugin.getRangedPrayer()
                )
        );
    }

    private void renderMagic()
    {
        addTitle(
                "MAGIC",
                Color.CYAN
        );

        addLine(
                "Weapon",
                plugin.getWeaponName(),
                Color.WHITE
        );

        if (plugin.getMagicBaseHit() <= 0)
        {
            addLine(
                    "MAX HIT",
                    "Set fallback",
                    Color.YELLOW
            );
        }
        else
        {
            addLine(
                    "MAX HIT",
                    String.valueOf(
                            plugin.getMagicMaxHit()
                    ),
                    Color.GREEN
            );
        }

        addLine(
                "Magic",
                String.valueOf(
                        plugin.getMagicLevel()
                ),
                Color.WHITE
        );

        addLine(
                "Base Hit",
                String.valueOf(
                        plugin.getMagicBaseHit()
                ),
                Color.WHITE
        );

        addLine(
                "Source",
                plugin.getMagicSource(),
                plugin
                        .isMagicAutomaticallyDetected()
                        ? Color.GREEN
                        : Color.YELLOW
        );

        addLine(
                "Magic Damage",
                formatPercent(
                        plugin.getMagicDamageBonus()
                ),
                Color.WHITE
        );

        addLine(
                "Prayer DMG",
                plugin.getMagicPrayerDamage()
                        + "%",
                Color.WHITE
        );

        addLine(
                "Style",
                plugin.getAttackStyle(),
                Color.WHITE
        );

        addLine(
                "Prayer",
                plugin.getMagicPrayer(),
                prayerColor(
                        plugin.getMagicPrayer()
                )
        );
    }

    private void addTitle(
            String text,
            Color color)
    {
        panelComponent
                .getChildren()
                .add(
                        TitleComponent.builder()
                                .text(text)
                                .color(color)
                                .build()
                );
    }

    private void addLine(
            String left,
            String right,
            Color rightColor)
    {
        panelComponent
                .getChildren()
                .add(
                        LineComponent.builder()
                                .left(left)
                                .leftColor(
                                        Color.LIGHT_GRAY
                                )
                                .right(right)
                                .rightColor(
                                        rightColor
                                )
                                .build()
                );
    }

    private String formatBonus(
            int value)
    {
        return value > 0
                ? "+" + value
                : String.valueOf(value);
    }

    private String formatPercent(
            float value)
    {
        return String.format(
                Locale.US,
                "%+.1f%%",
                value
        );
    }

    private Color prayerColor(
            String prayer)
    {
        if (
                prayer == null
                        || "None".equals(prayer)
        )
        {
            return Color.GRAY;
        }

        return Color.CYAN;
    }
}

package com.maxhitcalculator;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.ParamID;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.StructComposition;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
		name = "Max Hit Calculator",
		description = "Calculates melee, ranged and magic max hits.",
		tags = {"max hit", "combat", "gear", "calculator"}
)
public class MaxHitPlugin extends Plugin
{
	public enum CombatType
	{
		MELEE,
		RANGED,
		MAGIC
	}

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MaxHitOverlay maxHitOverlay;

	@Inject
	private MaxHitConfig config;

	private CombatType combatType = CombatType.MELEE;

	private int meleeMaxHit;
	private int strengthLevel;
	private int meleeStrengthBonus;
	private int meleeStyleBonus;

	private int rangedMaxHit;
	private int rangedLevel;
	private int rangedStrengthBonus;
	private int rangedStyleBonus;

	private int magicMaxHit;
	private int magicLevel;
	private float magicDamageBonus;
	private int magicBaseHit;
	private int magicPrayerDamage;

	private boolean magicAutomaticallyDetected;

	private String weaponName = "None";
	private String magicSource = "Manual";
	private String attackStyle = "Unknown";

	private String meleePrayer = "None";
	private String rangedPrayer = "None";
	private String magicPrayer = "None";

	private String[] currentWeaponStyles =
			new String[0];

	@Override
	protected void startUp()
	{
		overlayManager.add(maxHitOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(maxHitOverlay);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		calculateAll();
	}

	private void calculateAll()
	{
		ItemContainer equipment =
				client.getItemContainer(
						InventoryID.EQUIPMENT
				);

		if (equipment == null)
		{
			return;
		}

		strengthLevel =
				client.getBoostedSkillLevel(
						Skill.STRENGTH
				);

		rangedLevel =
				client.getBoostedSkillLevel(
						Skill.RANGED
				);

		magicLevel =
				client.getBoostedSkillLevel(
						Skill.MAGIC
				);

		calculateEquipmentBonuses(
				equipment
		);

		readWeapon(equipment);

		attackStyle =
				getCurrentAttackStyle();

		combatType =
				detectCombatType();

		calculateMelee();
		calculateRanged();
		calculateMagic();
	}

	private void calculateEquipmentBonuses(
			ItemContainer equipment)
	{
		meleeStrengthBonus = 0;
		rangedStrengthBonus = 0;
		magicDamageBonus = 0;

		for (Item item :
				equipment.getItems())
		{
			if (item.getId() <= 0)
			{
				continue;
			}

			ItemStats itemStats =
					itemManager.getItemStats(
							item.getId()
					);

			if (itemStats == null)
			{
				continue;
			}

			ItemEquipmentStats stats =
					itemStats.getEquipment();

			if (stats == null)
			{
				continue;
			}

			meleeStrengthBonus +=
					stats.getStr();

			rangedStrengthBonus +=
					stats.getRstr();

			magicDamageBonus +=
					stats.getMdmg();
		}
	}

	private void readWeapon(
			ItemContainer equipment)
	{
		weaponName = "None";

		Item weapon =
				equipment.getItem(
						EquipmentInventorySlot.WEAPON
								.getSlotIdx()
				);

		if (
				weapon == null
						|| weapon.getId() <= 0
		)
		{
			return;
		}

		ItemComposition composition =
				itemManager.getItemComposition(
						weapon.getId()
				);

		if (composition != null)
		{
			weaponName =
					composition.getName();
		}
	}

	/*
	 * =========================
	 * MELEE
	 * =========================
	 */

	private void calculateMelee()
	{
		double prayer =
				getMeleePrayerMultiplier();

		meleeStyleBonus =
				getMeleeStyleBonus(
						attackStyle
				);

		int effectiveStrength =
				(int) Math.floor(
						strengthLevel * prayer
				)
						+ meleeStyleBonus
						+ 8;

		meleeMaxHit =
				(int) Math.floor(
						0.5
								+ (
								effectiveStrength
										* (
										meleeStrengthBonus
												+ 64
								)
						)
								/ 640.0
				);
	}

	private double getMeleePrayerMultiplier()
	{
		meleePrayer = "None";

		if (client.isPrayerActive(
				Prayer.PIETY))
		{
			meleePrayer = "Piety";
			return 1.23;
		}

		if (client.isPrayerActive(
				Prayer.CHIVALRY))
		{
			meleePrayer = "Chivalry";
			return 1.18;
		}

		if (client.isPrayerActive(
				Prayer.ULTIMATE_STRENGTH))
		{
			meleePrayer =
					"Ultimate Strength";
			return 1.15;
		}

		if (client.isPrayerActive(
				Prayer.SUPERHUMAN_STRENGTH))
		{
			meleePrayer =
					"Superhuman Strength";
			return 1.10;
		}

		if (client.isPrayerActive(
				Prayer.BURST_OF_STRENGTH))
		{
			meleePrayer =
					"Burst of Strength";
			return 1.05;
		}

		return 1.0;
	}

	private int getMeleeStyleBonus(
			String style)
	{
		if ("Aggressive".equals(style))
		{
			return 3;
		}

		if ("Controlled".equals(style))
		{
			return 1;
		}

		return 0;
	}

	/*
	 * =========================
	 * RANGED
	 * =========================
	 */

	private void calculateRanged()
	{
		double prayer =
				getRangedPrayerMultiplier();

		rangedStyleBonus =
				getRangedStyleBonus(
						attackStyle
				);

		int effectiveRanged =
				(int) Math.floor(
						rangedLevel * prayer
				)
						+ rangedStyleBonus
						+ 8;

		rangedMaxHit =
				(int) Math.floor(
						0.5
								+ (
								effectiveRanged
										* (
										rangedStrengthBonus
												+ 64
								)
						)
								/ 640.0
				);
	}

	private double getRangedPrayerMultiplier()
	{
		rangedPrayer = "None";

		if (client.isPrayerActive(
				Prayer.RIGOUR))
		{
			rangedPrayer = "Rigour";
			return 1.23;
		}

		if (client.isPrayerActive(
				Prayer.DEADEYE))
		{
			rangedPrayer = "Deadeye";
			return 1.18;
		}

		if (client.isPrayerActive(
				Prayer.EAGLE_EYE))
		{
			rangedPrayer = "Eagle Eye";
			return 1.15;
		}

		if (client.isPrayerActive(
				Prayer.HAWK_EYE))
		{
			rangedPrayer = "Hawk Eye";
			return 1.10;
		}

		if (client.isPrayerActive(
				Prayer.SHARP_EYE))
		{
			rangedPrayer = "Sharp Eye";
			return 1.05;
		}

		return 1.0;
	}

	private int getRangedStyleBonus(
			String style)
	{
		if ("Accurate".equals(style))
		{
			return 3;
		}

		return 0;
	}

	/*
	 * =========================
	 * MAGIC
	 * =========================
	 */

	private void calculateMagic()
	{
		magicBaseHit =
				detectMagicBaseHit();

		magicPrayerDamage =
				getMagicPrayerDamageBonus();

		if (magicBaseHit <= 0)
		{
			magicMaxHit = 0;
			return;
		}

		float totalDamageBonus =
				magicDamageBonus
						+ magicPrayerDamage;

		magicMaxHit =
				(int) Math.floor(
						magicBaseHit
								* (
								1.0
										+ totalDamageBonus
										/ 100.0
						)
				);
	}

	private int detectMagicBaseHit()
	{
		magicAutomaticallyDetected = true;

		String name =
				weaponName.toLowerCase();

		/*
		 * Trident of the seas
		 *
		 * Base max:
		 * floor(Magic / 3) - 5
		 */
		if (
				name.contains(
						"trident of the seas"
				)
		)
		{
			magicSource =
					"Trident of the seas";

			return Math.max(
					0,
					(magicLevel / 3) - 5
			);
		}

		/*
		 * Trident of the swamp
		 *
		 * Base max:
		 * floor(Magic / 3) - 2
		 */
		if (
				name.contains(
						"trident of the swamp"
				)
		)
		{
			magicSource =
					"Trident of the swamp";

			return Math.max(
					0,
					(magicLevel / 3) - 2
			);
		}

		/*
		 * Sanguinesti staff
		 *
		 * Base max:
		 * floor(Magic / 3) - 1
		 */
		if (
				name.contains(
						"sanguinesti staff"
				)
		)
		{
			magicSource =
					"Sanguinesti staff";

			return Math.max(
					0,
					(magicLevel / 3) - 1
			);
		}

		/*
		 * Unknown spell/staff:
		 * use the RuneLite config value.
		 */
		magicAutomaticallyDetected =
				false;

		magicSource =
				"Fallback setting";

		return config.magicBaseHit();
	}

	private int getMagicPrayerDamageBonus()
	{
		magicPrayer = "None";

		if (client.isPrayerActive(
				Prayer.AUGURY))
		{
			magicPrayer = "Augury";
			return 4;
		}

		if (client.isPrayerActive(
				Prayer.MYSTIC_VIGOUR))
		{
			magicPrayer =
					"Mystic Vigour";
			return 3;
		}

		if (client.isPrayerActive(
				Prayer.MYSTIC_MIGHT))
		{
			magicPrayer =
					"Mystic Might";
			return 2;
		}

		if (client.isPrayerActive(
				Prayer.MYSTIC_LORE))
		{
			magicPrayer =
					"Mystic Lore";
			return 1;
		}

		if (client.isPrayerActive(
				Prayer.MYSTIC_WILL))
		{
			magicPrayer =
					"Mystic Will";
		}

		return 0;
	}

	/*
	 * =========================
	 * COMBAT TYPE
	 * =========================
	 */

	private CombatType detectCombatType()
	{
		if (
				"Casting".equals(attackStyle)
						|| "Defensive Casting"
						.equals(attackStyle)
		)
		{
			return CombatType.MAGIC;
		}

		/*
		 * Powered staves can be identified
		 * from the equipped weapon even when
		 * their interface doesn't look exactly
		 * like ordinary autocasting.
		 */
		if (isPoweredMagicWeapon())
		{
			return CombatType.MAGIC;
		}

		if (
				"Ranging".equals(attackStyle)
						|| "Rapid".equals(attackStyle)
						|| "Longrange".equals(attackStyle)
		)
		{
			return CombatType.RANGED;
		}

		if ("Accurate".equals(attackStyle))
		{
			if (
					weaponHasStyle("Ranging")
							|| weaponHasStyle("Rapid")
							|| weaponHasStyle(
							"Longrange"
					)
			)
			{
				return CombatType.RANGED;
			}
		}

		return CombatType.MELEE;
	}

	private boolean isPoweredMagicWeapon()
	{
		String name =
				weaponName.toLowerCase();

		return
				name.contains(
						"trident of the seas"
				)
						|| name.contains(
						"trident of the swamp"
				)
						|| name.contains(
						"sanguinesti staff"
				);
	}

	private boolean weaponHasStyle(
			String style)
	{
		for (
				String weaponStyle :
				currentWeaponStyles
		)
		{
			if (style.equals(weaponStyle))
			{
				return true;
			}
		}

		return false;
	}

	/*
	 * =========================
	 * ATTACK STYLE
	 * =========================
	 */

	private String getCurrentAttackStyle()
	{
		try
		{
			int styleIndex =
					client.getVarpValue(
							VarPlayerID.COM_MODE
					);

			int weaponType =
					client.getVarbitValue(
							VarbitID
									.COMBAT_WEAPON_CATEGORY
					);

			int defensiveCasting =
					client.getVarbitValue(
							VarbitID
									.AUTOCAST_DEFMODE
					);

			currentWeaponStyles =
					getWeaponStyles(
							weaponType
					);

			if (styleIndex == 4)
			{
				styleIndex +=
						defensiveCasting;
			}

			if (
					styleIndex < 0
							|| styleIndex
							>= currentWeaponStyles
							.length
			)
			{
				return "Unknown";
			}

			String style =
					currentWeaponStyles[
							styleIndex
							];

			if (style == null)
			{
				return "Unknown";
			}

			return style;
		}
		catch (Exception ex)
		{
			currentWeaponStyles =
					new String[0];

			return "Unknown";
		}
	}

	private String[] getWeaponStyles(
			int weaponType)
	{
		try
		{
			int styleEnum =
					client.getEnum(
									EnumID.WEAPON_STYLES
							)
							.getIntValue(
									weaponType
							);

			if (styleEnum == -1)
			{
				return new String[0];
			}

			int[] structs =
					client.getEnum(styleEnum)
							.getIntVals();

			String[] styles =
					new String[
							structs.length
							];

			for (
					int i = 0;
					i < structs.length;
					i++
			)
			{
				StructComposition struct =
						client
								.getStructComposition(
										structs[i]
								);

				String styleName =
						struct.getStringValue(
								ParamID
										.ATTACK_STYLE_NAME
						);

				if (
						styleName == null
								|| styleName.isEmpty()
				)
				{
					continue;
				}

				if (
						i == 5
								&& "defensive"
								.equalsIgnoreCase(
										styleName
								)
				)
				{
					styles[i] =
							"Defensive Casting";

					continue;
				}

				styles[i] =
						formatStyleName(
								styleName
						);
			}

			return styles;
		}
		catch (Exception ex)
		{
			return new String[0];
		}
	}

	private String formatStyleName(
			String style)
	{
		String lower =
				style.toLowerCase();

		switch (lower)
		{
			case "accurate":
				return "Accurate";

			case "aggressive":
				return "Aggressive";

			case "controlled":
				return "Controlled";

			case "defensive":
				return "Defensive";

			case "ranging":
				return "Ranging";

			case "rapid":
				return "Rapid";

			case "longrange":
				return "Longrange";

			case "casting":
				return "Casting";

			default:
				return
						Character.toUpperCase(
								style.charAt(0)
						)
